/bin/bash -lc "python3 /workspace/tools.py resolve run://r-001 | python3 -c 'import json,sys,pathlib; r=json.load(sys.stdin); p=json.loads(pathlib.Path(\"proposal.json\").read_text()); s=r[\"study_schema\"]
