 t=s.get(\"type\"); assert t"'!="object" or isinstance(x,dict),path; assert t!="array" or isinstance(x,list),path; assert t!="string" or isinstance(x,str),path
 if "enum" in s: assert x in s["enum"],path
 if "const" in s: assert x==s["const"],path
