  assert set(s.get("required",[]))<=set(x),path
  if s.get("additionalProperties")==False: assert set(x)<=set(s.get("properties",{})),path
  for k,v in x.items():
   if k in s.get("properties",{}): check(v,s["properties"][k],path+"."+k)
 if isinstance(x,list):
  assert len(x)>=s.get("minItems",0),path
